import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, basename } from 'node:path';
import { parseArgs } from './lib/argparse.mjs';
import { createSchema, createIn } from './lib/index.mjs';
import { parseQuery } from './lib/qparser.mjs';

const prog = basename(process.argv[1] || 'test18.mjs');
const args = parseArgs(process.argv.slice(2), prog);

const schema = createSchema({ title: { stored: true }, content: {} });
const tempDir = mkdtempSync(join(tmpdir(), 'test18-'));
const ix = createIn(tempDir, schema);
const writer = ix.writer();
const inputs = [args.a, args.b, args.c, args.d, args.e, args.f, args.g, args.h, args.i, args.j];
for (let i = 0; i < inputs.length; i++) {
  writer.addDocument({ title: `doc${i}`, content: inputs[i] });
}
writer.commit();
const searcher = ix.searcher();
let count = 0;
for (let i = 0; i < inputs.length; i++) {
  const query = parseQuery(inputs[i], ['title', 'content'], 'content');
  count += searcher.search(query).length;
}
console.log(count);

