// In-memory stand-in for whoosh's file index (create_in / writer / searcher).

import { analyze } from './analyzer.mjs';
import { execute } from './query.mjs';

export function createSchema(fieldsObj) {
  return { names: Object.keys(fieldsObj), fields: fieldsObj };
}

export function createIn(dir, schema) {
  const index = {
    dir,
    schema,
    docCount: 0,
    // field name -> Map(term -> Set(docId))
    postings: new Map(schema.names.map((name) => [name, new Map()])),
    // docId -> Map(field name -> token array)
    docTokens: new Map(),

    writer() {
      return {
        addDocument(fieldsObj) {
          const docId = index.docCount++;
          const tokens = new Map();
          for (const name of index.schema.names) {
            const value = fieldsObj[name];
            const fieldTokens =
              value === undefined || value === null
                ? []
                : analyze(String(value));
            tokens.set(name, fieldTokens);
            const fieldPostings = index.postings.get(name);
            for (const tok of new Set(fieldTokens)) {
              let docIds = fieldPostings.get(tok);
              if (!docIds) {
                docIds = new Set();
                fieldPostings.set(tok, docIds);
              }
              docIds.add(docId);
            }
          }
          index.docTokens.set(docId, tokens);
        },
        commit() {},
      };
    },

    searcher() {
      return {
        search(query) {
          return execute(query, index);
        },
      };
    },
  };
  return index;
}

