// Minimal emulation of Python's argparse for this exact parser definition:
//
//   parser = argparse.ArgumentParser()
//   for i in range(10):
//       parser.add_argument(f'--{chr(97+i)}', type=str, required=True)
//   args = parser.parse_args()
//
// i.e. ten required string options --a through --j, plus automatic -h/--help.

const OPTION_NAMES = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j'];
const LONG_NAMES = [...OPTION_NAMES, 'help'];
const USAGE_WIDTH = 80;

function isNegativeNumber(s) {
  return /^-\d+$/.test(s) || /^-\d*\.\d+$/.test(s);
}

// argparse treats a token as an option string if it starts with '-', is longer
// than one char, and does not look like a negative number.
function looksLikeOption(s) {
  return s.length > 1 && s.startsWith('-') && !isNegativeNumber(s);
}

function buildUsage(prog) {
  const parts = ['[-h]', ...OPTION_NAMES.map((n) => `--${n} ${n.toUpperCase()}`)];
  const prefix = `usage: ${prog} `;
  const indent = ' '.repeat(prefix.length);
  const lines = [];
  let line = prefix;
  for (const part of parts) {
    if (line === prefix || line === indent) {
      line += part;
    } else if ((line + ' ' + part).length > USAGE_WIDTH) {
      lines.push(line);
      line = indent + part;
    } else {
      line += ' ' + part;
    }
  }
  lines.push(line);
  return lines.join('\n');
}

function buildHelp(prog) {
  const lines = [buildUsage(prog), '', 'options:', '  -h, --help  show this help message and exit'];
  for (const n of OPTION_NAMES) {
    lines.push(`  --${n} ${n.toUpperCase()}`);
  }
  return lines.join('\n');
}

function fail(prog, message) {
  process.stderr.write(buildUsage(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelpAndExit(prog) {
  process.stdout.write(buildHelp(prog) + '\n');
  process.exit(0);
}

// Resolve a long option name (without the leading dashes) to its full name,
// allowing unambiguous abbreviations. Returns the full name, or calls fail
// on ambiguity, or returns null when nothing matches.
function resolveLong(prog, name) {
  if (LONG_NAMES.includes(name)) return name;
  const matches = LONG_NAMES.filter((n) => n.startsWith(name));
  if (matches.length === 1) return matches[0];
  if (matches.length > 1) {
    fail(prog, `ambiguous option: --${name} could match ${matches.map((m) => `--${m}`).join(', ')}`);
  }
  return null;
}

export function parseArgs(argv, prog) {
  const values = {};
  const seen = new Set();
  const extras = [];
  let positionalOnly = false;

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (positionalOnly) {
      extras.push(token);
      continue;
    }

    if (token === '--') {
      positionalOnly = true;
      continue;
    }

    if (token.startsWith('--')) {
      const body = token.slice(2);
      const eq = body.indexOf('=');
      const name = eq === -1 ? body : body.slice(0, eq);
      const resolved = resolveLong(prog, name);
      if (resolved === null) {
        extras.push(token);
        continue;
      }
      if (resolved === 'help') {
        printHelpAndExit(prog);
      }
      let value;
      if (eq !== -1) {
        value = body.slice(eq + 1);
      } else {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          fail(prog, `argument --${resolved}: expected one argument`);
        }
        value = next;
        i++;
      }
      values[resolved] = value;
      seen.add(resolved);
      continue;
    }

    if (looksLikeOption(token)) {
      if (token === '-h') {
        printHelpAndExit(prog);
      }
      extras.push(token);
      continue;
    }

    // Bare positional (including a lone '-'); this parser defines none.
    extras.push(token);
  }

  const missing = OPTION_NAMES.filter((n) => !seen.has(n));
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.map((n) => `--${n}`).join(', ')}`);
  }

  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  const result = {};
  for (const n of OPTION_NAMES) result[n] = values[n];
  return result;
}

