// qparser.mjs — reimplementation of whoosh's QueryParser behavior.
// Pure Node.js ESM, no dependencies.

import { analyze } from './analyzer.mjs';
import * as q from './query.mjs';

// Operators are recognized only when a WORD chunk is EXACTLY one of these
// (case-sensitive).
const OP_AND = new Set(['AND', '&']);
const OP_OR = new Set(['OR', '|']);
const OP_NOT = 'NOT';
const OP_ANDMAYBE = 'ANDMAYBE';
const OPERATORS = new Set(['AND', 'OR', 'NOT', '&', '|', 'ANDMAYBE']);

const BOOST_ONLY = /^\^\d+(\.\d+)?$/;      // standalone "^N" chunk
const BOOST_TRAIL = /\^\d+(\.\d+)?$/;      // trailing "^N" on a chunk
const FIELD_PREFIX = /^([\w.]+):([\s\S]*)$/;

// ---------------------------------------------------------------------------
// Lexer
// ---------------------------------------------------------------------------
function lex(text) {
  const tokens = [];
  const n = text.length;
  let i = 0;
  const isWs = (c) => /\s/.test(c);
  const wordStops = new Set(['(', ')', '"', "'", '[', '{']);

  while (i < n) {
    const c = text[i];
    if (isWs(c)) { i++; continue; }
    if (c === '(') { tokens.push({ t: 'LP' }); i++; continue; }
    if (c === ')') { tokens.push({ t: 'RP' }); i++; continue; }
    if (c === '"' || c === "'") {
      // PHRASE / SQUOTE: read until matching quote or end of string.
      // An unbalanced quote is not an error; content runs to end of string.
      let j = i + 1;
      while (j < n && text[j] !== c) j++;
      tokens.push({ t: c === '"' ? 'PHRASE' : 'SQUOTE', content: text.slice(i + 1, j) });
      i = j < n ? j + 1 : j;
      continue;
    }
    if (c === '[' || c === '{') {
      // RANGE: read until the first ']' or '}' (inclusive) or end of string.
      let j = i + 1;
      while (j < n && text[j] !== ']' && text[j] !== '}') j++;
      tokens.push({
        t: 'RANGE',
        content: text.slice(i + 1, j),
        open: c,
        close: j < n ? text[j] : '',
      });
      i = j < n ? j + 1 : j;
      continue;
    }
    // WORD chunk: read until whitespace or a special start char.
    let j = i;
    while (j < n && !isWs(text[j]) && !wordStops.has(text[j])) j++;
    tokens.push({ t: 'WORD', text: text.slice(i, j) });
    i = j;
  }
  return tokens;
}

// ---------------------------------------------------------------------------
// Parser (precedence climbing: OR < AND/adjacency/ANDMAYBE < NOT)
// ---------------------------------------------------------------------------
export function parseQuery(text, fieldNames, defaultField) {
  const tokens = lex(text);
  if (tokens.length === 0) return q.nullQuery();

  let pos = 0;
  const peek = () => tokens[pos];
  const peekWord = (w) => {
    const t = tokens[pos];
    return t !== undefined && t.t === 'WORD' && t.text === w;
  };
  const peekWordIn = (set) => {
    const t = tokens[pos];
    return t !== undefined && t.t === 'WORD' && set.has(t.text);
  };
  // Standalone "^N" chunks attach to the previous clause and are ignored.
  const skipBoosts = () => {
    while (pos < tokens.length) {
      const t = tokens[pos];
      if (t.t === 'WORD' && BOOST_ONLY.test(t.text)) pos++;
      else break;
    }
  };

  function parseOr(field) {
    // Leading OR with no left operand: just parse what follows.
    while (peekWordIn(OP_OR)) pos++;
    let left = parseAnd(field);
    while (peekWordIn(OP_OR)) {
      pos++;
      const right = parseAnd(field);
      left = q.or([left, right]);
    }
    return left;
  }

  function parseAnd(field) {
    skipBoosts();
    // Leading AND with no left operand: just parse what follows.
    while (peekWordIn(OP_AND)) { pos++; skipBoosts(); }
    let left = parseUnary(field);
    while (true) {
      skipBoosts();
      if (peekWordIn(OP_AND)) {
        pos++;
        skipBoosts();
        left = q.and([left, parseUnary(field)]);
      } else if (peekWord(OP_ANDMAYBE)) {
        pos++;
        skipBoosts();
        left = q.andMaybe(left, parseUnary(field));
      } else if (startsClause()) {
        // Implicit adjacency = AND.
        left = q.and([left, parseUnary(field)]);
      } else {
        break;
      }
    }
    return left;
  }

  function startsClause() {
    const t = peek();
    if (t === undefined || t.t === 'RP') return false;
    if (t.t === 'WORD' && OPERATORS.has(t.text) && t.text !== OP_NOT) return false;
    return true;
  }

  function parseUnary(field) {
    skipBoosts();
    if (peekWord(OP_NOT)) {
      pos++;
      return q.not(parseUnary(field));
    }
    return parsePrimary(field);
  }

  function parsePrimary(field) {
    const tok = peek();
    if (tok === undefined || tok.t === 'RP') return q.nullQuery();
    if (tok.t === 'WORD' && OPERATORS.has(tok.text)) return q.nullQuery();

    if (tok.t === 'LP') {
      pos++;
      const inner = parseOr(field); // field override applies to all leaves inside
      if (peek() !== undefined && peek().t === 'RP') pos++;
      return inner;
    }
    if (tok.t === 'PHRASE') {
      pos++;
      return phraseNode(field, tok.content);
    }
    if (tok.t === 'SQUOTE') {
      pos++;
      return analyzedWord(field, tok.content);
    }
    if (tok.t === 'RANGE') {
      pos++;
      return rangeNode(field, tok);
    }
    // WORD chunk
    pos++;
    return wordChunkNode(field, tok.text);
  }

  function wordChunkNode(field, text) {
    let negated = false;
    // 1. Optional single leading '+', then optional single leading '-'.
    if (text.startsWith('+')) text = text.slice(1);
    if (text.startsWith('-')) { text = text.slice(1); negated = true; }
    // 2. Optional trailing boost: strip "^N" and ignore it.
    text = text.replace(BOOST_TRAIL, '');
    // 3. Optional field prefix.
    const m = text.match(FIELD_PREFIX);
    if (m && fieldNames.includes(m[1])) {
      field = m[1];
      text = m[2];
      if (text === '') {
        // Field prefix applies to the NEXT clause (phrase/group/range/word).
        const nt = peek();
        if (nt !== undefined && nt.t !== 'RP' &&
            !(nt.t === 'WORD' && OPERATORS.has(nt.text))) {
          const r = parsePrimary(field);
          return negated ? q.not(r) : r;
        }
      }
    }
    // 4-6. Build the leaf from the remaining text.
    let node;
    if (/^\*+$/.test(text)) {
      node = q.every(field);
    } else if (text.includes('*') || text.includes('?')) {
      node = q.wildcard(field, text.toLowerCase());
    } else {
      node = analyzedWord(field, text);
    }
    return negated ? q.not(node) : node;
  }

  function analyzedWord(field, text) {
    const toks = analyze(text);
    if (toks.length === 0) return q.nullQuery();
    if (toks.length === 1) return q.term(field, toks[0]);
    return q.and(toks.map((t) => q.term(field, t)));
  }

  function phraseNode(field, content) {
    const toks = analyze(content);
    if (toks.length === 0) return q.nullQuery();
    if (toks.length === 1) return q.term(field, toks[0]);
    return q.phrase(field, toks);
  }

  function rangeNode(field, tok) {
    const parts = tok.content.split(/\s+TO\s+/);
    if (parts.length === 2) {
      const start = parts[0].trim().toLowerCase() || null;
      const end = parts[1].trim().toLowerCase() || null;
      return q.termRange(field, start, end, tok.open === '{', tok.close === '}');
    }
    // No ' TO ' separator: treat inner text as ordinary word text.
    return analyzedWord(field, tok.content);
  }

  return parseOr(defaultField);
}

